/// <summary>
/// The <c>AVAWHSProcessGuidePromptChangePrinterPageBuilder</c> class builds a page that allows the user to change the current selected printer
/// </summary>
[
    ProcessGuidePageBuilderName(classStr(AVAWHSProcessGuidePromptChangePrinterPageBuilder))
]
class AVAWHSProcessGuidePromptChangePrinterPageBuilder extends ProcessGuidePageBuilder
{
    #WHSRF

}

Method.Source:
protected final void addDataControls(ProcessGuidePage _page)
{ 
    WhsrfPassthrough    pass            = controller.parmSessionState().parmPass();
    WHSUserId           userId          = pass.lookupStr(ProcessGuideDataTypeNames::UserId);
    WHSRFMenuItemTable  menuItemTable; 

    if (pass.exists(#MenuItem))
    { 
        menuItemTable = WHSRFMenuItemTable::find(pass.lookupStr(#MenuItem));
    }

    if (menuItemTable.AVAPreferredInputType == AVAWHSPreferredInputType::Select)
    { 
        _page.addComboBox(ProcessGuideDataTypeNames::AVAPrinterCode, "@WAX3207", extendedTypeNum(AVAPrinterCode), AVAWHSWorkUserPrinter::getPrinterCodesByUser(userId), true, pass.avaParmPrinterCode()); 
    }
    else
    { 
        _page.addLabel(ProcessGuideDataTypeNames::Scan, "@NDX:AVAScanPrinter", extendedTypeNum(WHSRFUndefinedDataType));
        _page.addTextBox(ProcessGuideDataTypeNames::AVAPrinterCode, "@NDX:AVAPrinterCode", extendedTypeNum(AVAPrinterCode));
    }    
}
